I'll update the files to change the counter to start at 10 and modify the button text to show "Clicked N times" after each click.

```javascript path=app.js
// Get the counter element and button from the DOM
const counterElement = document.getElementById('counter');
const incrementBtn = document.getElementById('incrementBtn');

// Initialize counter
let counter = 10;

// Update the counter display
function updateCounter() {
    counterElement.textContent = counter;
    incrementBtn.textContent = `Clicked ${counter} times`;
}

// Add click event listener to the button
incrementBtn.addEventListener('click', () => {
    counter++;
    updateCounter();
});
```

